-- Rebuild Medina Book 3 lesson 8 strictly from the supplied Arabic sharh.
-- Canonical page references: Sharkh_Medinskiy_3.pdf, PDF pages 36-38.

begin;
do $migration$
declare old_rule_count integer; new_rule_count integer; source_count integer;
begin
  select count(*) into old_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '8';
  if old_rule_count <> 7 then raise exception 'Expected 7 generated Book 3 lesson 8 rules, found %', old_rule_count; end if;

  delete from public.rule_sections where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '8');
  delete from public.rule_sources where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '8');
  delete from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '8';

  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar)
  values
    ('Мединский курс (Том 3)', '8', 'الْمَعْرِفَةُ وَالنَّكِرَةُ (определённое и неопределённое имя)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">الْمَعْرِفَةُ</span> اِسْمٌ يَدُلُّ عَلَى مُعَيَّنٍ، وَ<span class="ar-tone-structure">النَّكِرَةُ</span> اِسْمٌ يَدُلُّ عَلَى غَيْرِ مُعَيَّنٍ.</span><p class="rule-study-text">Определённое имя называет конкретное лицо, предмет или понятие; неопределённое имя указывает не на конкретный объект.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры из шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид имени</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْرِفَةُ</span><span class="rule-table-ru">определённое имя</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنْتَ، مُحَمَّدٌ، هَذَا، الَّذِي، الْمُدَرِّسُ، كِتَابُ الْجَامِعَةِ</span><span class="rule-table-ru">ты; Мухаммад; этот; который; учитель; книга университета</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّكِرَةُ</span><span class="rule-table-ru">неопределённое имя</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">رَجُلٌ، كِتَابٌ، جَامِعَةٌ</span><span class="rule-table-ru">мужчина; книга; университет</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Семь видов определённых имён</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الرَّقْمُ</span><span class="rule-table-ru">номер</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قِسْمُ الْمَعْرِفَةِ</span><span class="rule-table-ru">вид определённого имени</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">١</span><span class="rule-table-ru">1</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الضَّمِيرُ</span><span class="rule-table-ru">местоимение</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَفْظٌ لِلْكِنَايَةِ</span><span class="rule-table-ru">слово-заместитель</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٢</span><span class="rule-table-ru">2</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْعَلَمُ</span><span class="rule-table-ru">имя собственное</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْمٌ يُعَيِّنُ مُسَمَّاهُ</span><span class="rule-table-ru">имя, прямо называющее объект</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٣</span><span class="rule-table-ru">3</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمُ الْإِشَارَةِ</span><span class="rule-table-ru">указательное имя</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَفْظٌ لِلْإِشَارَةِ</span><span class="rule-table-ru">слово для указания</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٤</span><span class="rule-table-ru">4</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الِاسْمُ الْمَوْصُولُ</span><span class="rule-table-ru">относительное имя</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْمٌ تَتْبَعُهُ صِلَةٌ</span><span class="rule-table-ru">имя, после которого идёт поясняющая связь</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٥</span><span class="rule-table-ru">5</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُعَرَّفُ بِـ«أَلْ»</span><span class="rule-table-ru">имя, определённое артиклем «аль»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">دَخَلَتْ عَلَيْهِ «أَلْ»</span><span class="rule-table-ru">к нему присоединён артикль «аль»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٦</span><span class="rule-table-ru">6</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُضَافُ إِلَى مَعْرِفَةٍ</span><span class="rule-table-ru">имя в идафе с определённым именем</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اُكْتُسِبَ التَّعْرِيفُ بِالْإِضَافَةِ</span><span class="rule-table-ru">определённость получена через идафу</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">٧</span><span class="rule-table-ru">7</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّكِرَةُ الْمَقْصُودَةُ بِالنِّدَاءِ</span><span class="rule-table-ru">намеренно определённое обращением неопределённое имя</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قُصِدَ تَعْيِينُهَا بِالنِّدَاءِ</span><span class="rule-table-ru">конкретный адресат определяется обращением</span></td></tr></tbody></table></div></div></div>', 1, 'rule', 'Определённое имя указывает на конкретный объект, неопределённое — на неконкретный; шарх перечисляет семь видов определённых имён.', 'الْمَعْرِفَةُ اِسْمٌ يَدُلُّ عَلَى مُعَيَّنٍ، وَالنَّكِرَةُ اِسْمٌ يَدُلُّ عَلَى غَيْرِ مُعَيَّنٍ، وَالْمَعَارِفُ سَبْعَةُ أَقْسَامٍ.'),
    ('Мединский курс (Том 3)', '8', 'الضَّمِيرُ (местоимение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-subject">الضَّمِيرُ</span> لَفْظٌ مَوْضُوعٌ لِلْكِنَايَةِ عَنِ الْمُتَكَلِّمِ أَوِ الْمُخَاطَبِ أَوِ الْغَائِبِ نِيَابَةً عَنِ الْأَسْمَاءِ الظَّاهِرَةِ، وَفَائِدَتُهُ الِاخْتِصَارُ.</span><p class="rule-study-text">Местоимение употребляется вместо явно названного имени говорящего, собеседника или отсутствующего лица. Его польза — краткость.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Деление по значению</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقِسْمُ</span><span class="rule-table-ru">разряд</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الضَّمَائِرُ</span><span class="rule-table-ru">местоимения</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَمْثِلَةٌ مُتَّصِلَةٌ</span><span class="rule-table-ru">присоединённые формы из шарха</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَمِيرُ الْمُتَكَلِّمِ</span><span class="rule-table-ru">местоимение говорящего</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَنَا، نَحْنُ</span><span class="rule-table-ru">я; мы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">—</span><span class="rule-table-ru">—</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَمِيرُ الْمُخَاطَبِ</span><span class="rule-table-ru">местоимение собеседника</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَنْتَ، أَنْتِ، أَنْتُمَا، أَنْتُمْ، أَنْتُنَّ</span><span class="rule-table-ru">ты (м.); ты (ж.); вы двое; вы (м.); вы (ж.)</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">التَّاءُ فِي قُمْتَ وَقُمْتِ؛ وَالْكَافُ فِي رَأَيْتُكَ وَرَأَيْتُكِ</span><span class="rule-table-ru">окончание ـتَ/ـتِ в «ты встал/встала»; ـكَ/ـكِ в «я увидел тебя»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَمِيرُ الْغَائِبِ</span><span class="rule-table-ru">местоимение отсутствующего</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">هُوَ، هِيَ، هُمَا، هُمْ، هُنَّ</span><span class="rule-table-ru">он; она; они двое; они (м.); они (ж.)</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْهَاءُ فِي رَأَيْتُهُ وَرَأَيْتُهَا؛ وَالنُّونُ فِي يَقُمْنَ</span><span class="rule-table-ru">ـهُ/ـهَا в «я увидел его/её»; ـنَ в «они (ж.) встают»</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Деление по употреблению</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقِسْمُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّقْدِيرُ وَالْمَعْنَى</span><span class="rule-table-ru">подразумеваемое местоимение и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">بَارِزٌ</span><span class="rule-table-ru">явно выраженное местоимение</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الضَّمَائِرُ السَّابِقَةُ</span><span class="rule-table-ru">предыдущие местоимения</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَلْفُوظٌ بِهِ</span><span class="rule-table-ru">произносится явно</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُسْتَتِرٌ</span><span class="rule-table-ru">скрытое местоимение</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ذَهَبَتْ</span><span class="rule-table-ru">она ушла</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">تَقْدِيرُهُ: هِيَ</span><span class="rule-table-ru">подразумевается «она»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُسْتَتِرٌ</span><span class="rule-table-ru">скрытое местоимение</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَخْرُجُ</span><span class="rule-table-ru">я выхожу</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">تَقْدِيرُهُ: أَنَا</span><span class="rule-table-ru">подразумевается «я»</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Важное замечание</span><span class="rule-main-ar ar-tone-subject" dir="rtl" lang="ar">الضَّمَائِرُ كُلُّهَا مَبْنِيَّةٌ.</span><p class="rule-study-text">Все местоимения являются неизменяемыми словами.</p></div></div>', 2, 'rule', 'Местоимение заменяет явное имя; по значению местоимения делятся на говорящего, адресата и отсутствующего, а по употреблению — на явные и скрытые.', 'الضَّمِيرُ لَفْظٌ مَوْضُوعٌ لِلْكِنَايَةِ عَنِ الْمُتَكَلِّمِ أَوِ الْمُخَاطَبِ أَوِ الْغَائِبِ نِيَابَةً عَنِ الْأَسْمَاءِ الظَّاهِرَةِ، وَفَائِدَتُهُ الِاخْتِصَارُ. وَهُوَ بِاعْتِبَارِ مَعْنَاهُ ضَمِيرُ مُتَكَلِّمٍ أَوْ مُخَاطَبٍ أَوْ غَائِبٍ، وَبِاعْتِبَارِ اسْتِعْمَالِهِ بَارِزٌ أَوْ مُسْتَتِرٌ، وَالضَّمَائِرُ كُلُّهَا مَبْنِيَّةٌ.'),
    ('Мединский курс (Том 3)', '8', 'الْعَلَمُ (имя собственное)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-subject">الْعَلَمُ</span> اِسْمٌ يُعَيِّنُ مُسَمَّاهُ بِلَا قَرِينَةٍ.</span><p class="rule-study-text">Имя собственное указывает на конкретно названное лицо или место без дополнительного признака.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры из шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعَلَمُ</span><span class="rule-table-ru">имя собственное</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русское написание или смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُحَمَّدٌ</span><span class="rule-table-ru">Мухаммад</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْمُ شَخْصٍ</span><span class="rule-table-ru">имя человека</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">عَلِيٌّ</span><span class="rule-table-ru">Али</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْمُ شَخْصٍ</span><span class="rule-table-ru">имя человека</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">عَبْدُ الرَّحْمَنِ</span><span class="rule-table-ru">Абдуррахман</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْمُ شَخْصٍ</span><span class="rule-table-ru">имя человека</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَكَّةُ</span><span class="rule-table-ru">Мекка</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْمُ مَكَانٍ</span><span class="rule-table-ru">название места</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَرْيَمُ</span><span class="rule-table-ru">Марьям</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْمُ شَخْصٍ</span><span class="rule-table-ru">имя человека</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَبُو حَامِدٍ</span><span class="rule-table-ru">Абу Хамид</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كُنْيَةٌ</span><span class="rule-table-ru">кунья</span></td></tr></tbody></table></div></div></div>', 3, 'rule', 'Имя собственное прямо определяет названное лицо или место без дополнительного указателя.', 'الْعَلَمُ اِسْمٌ يُعَيِّنُ مُسَمَّاهُ بِلَا قَرِينَةٍ.'),
    ('Мединский курс (Том 3)', '8', 'اسْمُ الْإِشَارَةِ (указательное имя)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">اسْمُ الْإِشَارَةِ</span> لَفْظٌ مَوْضُوعٌ لِلدَّلَالَةِ عَلَى الْمُشَارِ إِلَيْهِ.</span><p class="rule-study-text">Указательное имя — слово, предназначенное для указания на называемый объект.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Указательные имена из шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمُ الْإِشَارَةِ</span><span class="rule-table-ru">указательное имя</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَذَا</span><span class="rule-table-ru">этот</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْمُفْرَدِ الْمُذَكَّرِ</span><span class="rule-table-ru">для единственного мужского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَذِهِ</span><span class="rule-table-ru">эта</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْمُفْرَدَةِ الْمُؤَنَّثَةِ</span><span class="rule-table-ru">для единственного женского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَذَانِ</span><span class="rule-table-ru">эти двое (м.)</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْمُثَنَّى الْمُذَكَّرِ</span><span class="rule-table-ru">для двойственного мужского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَاتَانِ</span><span class="rule-table-ru">эти две (ж.)</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْمُثَنَّى الْمُؤَنَّثِ</span><span class="rule-table-ru">для двойственного женского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هَؤُلَاءِ</span><span class="rule-table-ru">эти</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْجَمْعِ</span><span class="rule-table-ru">для множественного числа</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ذَلِكَ</span><span class="rule-table-ru">тот</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْمُفْرَدِ الْمُذَكَّرِ</span><span class="rule-table-ru">для единственного мужского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تِلْكَ</span><span class="rule-table-ru">та</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْمُفْرَدَةِ الْمُؤَنَّثَةِ</span><span class="rule-table-ru">для единственного женского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ذَانِكَ</span><span class="rule-table-ru">те двое (м.)</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْمُثَنَّى الْمُذَكَّرِ</span><span class="rule-table-ru">для двойственного мужского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَانِكَ</span><span class="rule-table-ru">те две (ж.)</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْمُثَنَّى الْمُؤَنَّثِ</span><span class="rule-table-ru">для двойственного женского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أُولَئِكَ</span><span class="rule-table-ru">те</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْجَمْعِ</span><span class="rule-table-ru">для множественного числа</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Указание на место</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمُ الْإِشَارَةِ لِلْمَكَانِ</span><span class="rule-table-ru">указательное имя места</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هُنَا</span><span class="rule-table-ru">здесь</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَكَانٌ قَرِيبٌ</span><span class="rule-table-ru">близкое место</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هُنَاكَ</span><span class="rule-table-ru">там</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَكَانٌ بَعِيدٌ</span><span class="rule-table-ru">удалённое место</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هُنَالِكَ</span><span class="rule-table-ru">там</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَكَانٌ بَعِيدٌ</span><span class="rule-table-ru">удалённое место</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ثَمَّ</span><span class="rule-table-ru">там</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَكَانٌ بَعِيدٌ</span><span class="rule-table-ru">удалённое место</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Неизменяемость</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">أَسْمَاءُ الْإِشَارَةِ كُلُّهَا مَبْنِيَّةٌ مَا عَدَا الْمُثَنَّى مِنْهَا فَهُوَ مُعْرَبٌ.</span><p class="rule-study-text">Все указательные имена неизменяемы, кроме двойственных форм: они изменяются по падежам.</p></div></div>', 4, 'rule', 'Указательное имя указывает на объект; все указательные имена неизменяемы, кроме форм двойственного числа.', 'اسْمُ الْإِشَارَةِ لَفْظٌ مَوْضُوعٌ لِلدَّلَالَةِ عَلَى الْمُشَارِ إِلَيْهِ. أَسْمَاءُ الْإِشَارَةِ كُلُّهَا مَبْنِيَّةٌ إِلَّا صِيَغَ الْمُثَنَّى فَهِيَ مُعْرَبَةٌ.'),
    ('Мединский курс (Том 3)', '8', 'الِاسْمُ الْمَوْصُولُ وَصِلَتُهُ (относительное имя и его придаточная связь)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">الِاسْمُ الْمَوْصُولُ</span> اِسْمٌ يَدُلُّ عَلَى مُعَيَّنٍ بِوَاسِطَةِ جُمْلَةٍ تُذْكَرُ بَعْدَهُ وَتُسَمَّى <span class="ar-tone-predicate">صِلَةَ الْمَوْصُولِ</span>.</span><p class="rule-study-text">Относительное имя указывает на определённое лицо или предмет посредством следующей за ним части, называемой связью относительного имени.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Формы из шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الِاسْمُ الْمَوْصُولُ</span><span class="rule-table-ru">относительное имя</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الَّذِي</span><span class="rule-table-ru">который (м., ед.)</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْمُفْرَدِ الْمُذَكَّرِ</span><span class="rule-table-ru">для единственного мужского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الَّتِي</span><span class="rule-table-ru">которая</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْمُفْرَدَةِ الْمُؤَنَّثَةِ</span><span class="rule-table-ru">для единственного женского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اللَّذَانِ</span><span class="rule-table-ru">которые двое (м.)</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْمُثَنَّى الْمُذَكَّرِ</span><span class="rule-table-ru">для двойственного мужского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اللَّتَانِ</span><span class="rule-table-ru">которые две (ж.)</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْمُثَنَّى الْمُؤَنَّثِ</span><span class="rule-table-ru">для двойственного женского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الَّذِينَ</span><span class="rule-table-ru">которые (м.)</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِجَمْعِ الْمُذَكَّرِ</span><span class="rule-table-ru">для множественного мужского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اللَّائِي</span><span class="rule-table-ru">которые (ж.)</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِجَمْعِ الْمُؤَنَّثِ</span><span class="rule-table-ru">для множественного женского рода</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْ</span><span class="rule-table-ru">кто; тот, кто</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْعَاقِلِ</span><span class="rule-table-ru">для разумного</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا</span><span class="rule-table-ru">то, что</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِغَيْرِ الْعَاقِلِ</span><span class="rule-table-ru">для неразумного</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Строение примеров</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الِاسْمُ الْمَوْصُولُ</span><span class="rule-table-ru">относительное имя</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صِلَةُ الْمَوْصُولِ</span><span class="rule-table-ru">связующая часть</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعَائِدُ</span><span class="rule-table-ru">возвращающееся местоимение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">كَافَأْتُ الطُّلَّابَ الَّذِينَ نَجَحُوا.</span><span class="rule-table-ru">Я наградил студентов, которые преуспели.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الَّذِينَ</span><span class="rule-table-ru">которые</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">نَجَحُوا</span><span class="rule-table-ru">они преуспели</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْوَاوُ فِي نَجَحُوا</span><span class="rule-table-ru">буква «вау» в слове «преуспели»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جَاءَ مَنْ أَكْرَمْتُهُ.</span><span class="rule-table-ru">Пришёл тот, кого я почтил.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْ</span><span class="rule-table-ru">тот, кто</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَكْرَمْتُهُ</span><span class="rule-table-ru">я почтил его</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْهَاءُ فِي أَكْرَمْتُهُ</span><span class="rule-table-ru">ـهُ в слове «я почтил его»</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Два замечания</span><span class="rule-main-ar ar-tone-subject" dir="rtl" lang="ar">فِي جُمْلَةِ الصِّلَةِ ضَمِيرٌ يَعُودُ إِلَى الِاسْمِ الْمَوْصُولِ يُسَمَّى عَائِدًا.</span><p class="rule-study-text">В связующей части есть местоимение, которое возвращается к относительному имени; оно называется возвращающимся местоимением.</p><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">الْأَسْمَاءُ الْمَوْصُولَةُ كُلُّهَا مَبْنِيَّةٌ مَا عَدَا الْمُثَنَّى مِنْهَا فَهُوَ مُعْرَبٌ.</span><p class="rule-study-text">Все относительные имена неизменяемы, кроме двойственных форм.</p></div></div>', 5, 'rule', 'Относительное имя раскрывается следующей за ним связующей частью; внутри неё находится возвращающееся местоимение — عَائِدٌ.', 'الِاسْمُ الْمَوْصُولُ اِسْمٌ يَدُلُّ عَلَى مُعَيَّنٍ بِوَاسِطَةِ جُمْلَةٍ تُذْكَرُ بَعْدَهُ وَتُسَمَّى صِلَةَ الْمَوْصُولِ. وَفِي جُمْلَةِ الصِّلَةِ ضَمِيرٌ يَعُودُ إِلَى الِاسْمِ الْمَوْصُولِ يُسَمَّى عَائِدًا. وَالْأَسْمَاءُ الْمَوْصُولَةُ كُلُّهَا مَبْنِيَّةٌ إِلَّا صِيَغَ الْمُثَنَّى فَهِيَ مُعْرَبَةٌ.'),
    ('Мединский курс (Том 3)', '8', 'الْمُعَرَّفُ بِـ«أَلْ» (имя, определённое артиклем «аль»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">الْمُعَرَّفُ بِـ«أَلْ»</span> هُوَ الِاسْمُ النَّكِرَةُ الَّذِي يَكْتَسِبُ التَّعْرِيفَ بِدُخُولِ «أَلْ» عَلَيْهِ.</span><p class="rule-study-text">Имя, определённое артиклем «аль», — это неопределённое имя, которое приобрело определённость после присоединения артикля.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Преобразование примеров</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّكِرَةُ</span><span class="rule-table-ru">неопределённое имя</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْرِفَةُ بِـ«أَلْ»</span><span class="rule-table-ru">имя с артиклем «аль»</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قَلَمٌ</span><span class="rule-table-ru">ручка; какая-то ручка</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقَلَمُ</span><span class="rule-table-ru">эта/известная ручка</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قَلَمٌ — الْقَلَمُ</span><span class="rule-table-ru">ручка — определённая ручка</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">رَجُلٌ</span><span class="rule-table-ru">мужчина; какой-то мужчина</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الرَّجُلُ</span><span class="rule-table-ru">этот/известный мужчина</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">رَجُلٌ — الرَّجُلُ</span><span class="rule-table-ru">мужчина — определённый мужчина</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَيْتٌ</span><span class="rule-table-ru">дом; какой-то дом</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْبَيْتُ</span><span class="rule-table-ru">этот/известный дом</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَيْتٌ — الْبَيْتُ</span><span class="rule-table-ru">дом — определённый дом</span></td></tr></tbody></table></div></div></div>', 6, 'rule', 'Неопределённое имя становится определённым после присоединения артикля أَلْ.', 'الْمُعَرَّفُ بِـ«أَلْ» هُوَ الِاسْمُ النَّكِرَةُ الَّذِي يَكْتَسِبُ التَّعْرِيفَ بِدُخُولِ «أَلْ» عَلَيْهِ.'),
    ('Мединский курс (Том 3)', '8', 'الْمُضَافُ إِلَى مَعْرِفَةٍ (имя в идафе с определённым именем)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">الْمُضَافُ إِلَى مَعْرِفَةٍ</span> اِسْمٌ نَكِرَةٌ يَكْتَسِبُ التَّعْرِيفَ بِإِضَافَتِهِ إِلَى وَاحِدٍ مِنَ الْمَعَارِفِ.</span><p class="rule-study-text">Неопределённое имя приобретает определённость, если становится первым членом идафы с одним из определённых имён.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Идафа к разным видам определённых имён</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ الْمُضَافِ إِلَيْهِ</span><span class="rule-table-ru">вид второго члена идафы</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِتَابُكَ</span><span class="rule-table-ru">твоя книга</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَمِيرٌ</span><span class="rule-table-ru">местоимение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِتَابُ مُحَمَّدٍ</span><span class="rule-table-ru">книга Мухаммада</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">عَلَمٌ</span><span class="rule-table-ru">имя собственное</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِتَابُ هَذَا</span><span class="rule-table-ru">книга этого человека</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمُ إِشَارَةٍ</span><span class="rule-table-ru">указательное имя</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِتَابُ الَّذِي زَارَنَا</span><span class="rule-table-ru">книга того, кто посетил нас</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِسْمٌ مَوْصُولٌ</span><span class="rule-table-ru">относительное имя</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِتَابُ الْمُعَلِّمِ</span><span class="rule-table-ru">книга учителя</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعَرَّفٌ بِـ«أَلْ»</span><span class="rule-table-ru">имя с артиклем «аль»</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Если второй член идафы неопределённый</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">الْمُضَافُ إِلَى نَكِرَةٍ يَبْقَى نَكِرَةً، وَلَكِنَّهُ يَسْتَفِيدُ التَّخْصِيصَ، أَيْ تَقْتَرِبُ دَرَجَتُهُ مِنَ الْمَعْرِفَةِ.</span><p class="rule-study-text">Первый член остаётся неопределённым, но становится более конкретным по смыслу.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры идафы к неопределённому имени</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِتَابُ طَالِبٍ</span><span class="rule-table-ru">книга какого-то студента</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَكِرَةٌ مُخَصَّصَةٌ</span><span class="rule-table-ru">уточнённое, но неопределённое сочетание</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كِتَابُ مُدَرِّسٍ</span><span class="rule-table-ru">книга какого-то преподавателя</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَكِرَةٌ مُخَصَّصَةٌ</span><span class="rule-table-ru">уточнённое, но неопределённое сочетание</span></td></tr></tbody></table></div></div></div>', 7, 'rule', 'Идафа к определённому имени делает первое слово определённым; идафа к неопределённому имени лишь уточняет его, не делая определённым.', 'الْمُضَافُ إِلَى مَعْرِفَةٍ اِسْمٌ نَكِرَةٌ يَكْتَسِبُ التَّعْرِيفَ بِإِضَافَتِهِ إِلَى وَاحِدٍ مِنَ الْمَعَارِفِ. وَالْمُضَافُ إِلَى نَكِرَةٍ يَبْقَى نَكِرَةً، وَلَكِنَّهُ يَسْتَفِيدُ التَّخْصِيصَ فَتَقْتَرِبُ دَرَجَتُهُ مِنَ الْمَعْرِفَةِ.'),
    ('Мединский курс (Том 3)', '8', 'النَّكِرَةُ الْمَقْصُودَةُ بِالنِّدَاءِ (неопределённое имя, обозначающее конкретного адресата)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">النَّكِرَةُ الْمَقْصُودَةُ بِالنِّدَاءِ</span> هِيَ اِسْمٌ نَكِرَةٌ قُصِدَ تَعْيِينُهُ بِالنِّدَاءِ.</span><p class="rule-study-text">Это неопределённое имя, которым при обращении намеренно обозначают конкретного адресата.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Конкретный адресат</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">грамматическое положение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">يَا رَجُلُ</span><span class="rule-table-ru">О мужчина! — обращение к конкретному мужчине</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَبْنِيٌّ عَلَى الضَّمِّ</span><span class="rule-table-ru">построено на дамме</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">يَا شَيْخُ</span><span class="rule-table-ru">О шейх!</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَكِرَةٌ مَقْصُودَةٌ</span><span class="rule-table-ru">конкретный адресат</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">يَا بِنْتُ</span><span class="rule-table-ru">О девушка!</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَكِرَةٌ مَقْصُودَةٌ</span><span class="rule-table-ru">конкретный адресат</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">يَا طَبِيبُ</span><span class="rule-table-ru">О врач!</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَكِرَةٌ مَقْصُودَةٌ</span><span class="rule-table-ru">конкретный адресат</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Сопоставление с двумя другими случаями</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">положение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">يَا رَجُلًا سَاعِدْنِي.</span><span class="rule-table-ru">Мужчина, помоги мне! — обращение к любому, не определённому заранее человеку</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَكِرَةٌ غَيْرُ مَقْصُودَةٍ</span><span class="rule-table-ru">неопределённое имя без конкретного адресата</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-table-ru">стоит в винительном падеже</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">يَا مُحَمَّدُ</span><span class="rule-table-ru">О Мухаммад!</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">عَلَمٌ</span><span class="rule-table-ru">имя собственное</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعْرِفَةٌ قَبْلَ النِّدَاءِ</span><span class="rule-table-ru">было определённым ещё до обращения</span></td></tr></tbody></table></div></div></div>', 8, 'rule', 'При обращении неопределённое имя может обозначить конкретного адресата; нецелевая неопределённая форма остаётся неопределённой и ставится в винительный падеж.', 'النَّكِرَةُ الْمَقْصُودَةُ بِالنِّدَاءِ هِيَ اِسْمٌ نَكِرَةٌ قُصِدَ تَعْيِينُهُ بِالنِّدَاءِ، وَفِي نَحْوِ «يَا رَجُلُ» تُبْنَى عَلَى الضَّمِّ. أَمَّا النَّكِرَةُ غَيْرُ الْمَقْصُودَةِ فَتَبْقَى نَكِرَةً وَتَكُونُ مَنْصُوبَةً. وَالْعَلَمُ لَا يَكْتَسِبُ التَّعْرِيفَ بِالنِّدَاءِ لِأَنَّهُ مَعْرِفَةٌ قَبْلَهُ.');

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', 'الدَّرْسُ الثَّامِنُ
الْمَعْرِفَةُ ، وَالنَّكِرَةُ
الْمَعْرِفَةُ ، هو : الاسمُ الذي دلَّ على مُعَيَّنٍ ، نحو : أنت ، ومُحَّمد ، وهذا ، والَّذي ،
والمدرَّس ، وكتاب الجامعةِ .
والنَّكِرَةُ ، هو : الاسمُ الذي دَلَّ على غيرِ مُعَيَّنٍ ، نحو : رجل ، وكتاب ، وجامعة .
أقسام المعرفة :
الْمَعَارِفُ سبعةُ أقسامٍ ، هي :', 36, 36, 1
  from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '8' and sort_order = 1;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
  select id, 'Sharkh_Medinskiy_3.pdf', '1- الضَّمِيرُ ، وهو : اللَّفْظُ الْمَوْضُوعُ لِلْكِنَايَةِ عن المتكلِّمِ ، أو المخاطَبِ ، أو الغائبِ نِيَابَةً عن الأسماء الظَّاهرة . وفائدته : الاخْتِصَارُ .
أقسام الضَّمير : ينقسم الضمير باعتبار معناه إلى ثلاثة أقسام ، هي :
أ- ضمير المتكلِّم ، نحو : أنا ، نحن .
ب- ضمير المخاطَب ، نحو : أنتَِ ، وأنتما ، وأنتم ، وأَنْتُنَّ ؛ والتاء في قمتَِ ؛ والكاف
في رأيتكَِ .
ج- ضمير الغائب ، نحو : هو ، هي ، هما ، هم ، هُنَّ ؛ والهاء في رأيته ، ورأيتها ؛ والنون في يَقُمْنَ .
وينقسم باعتبار اسْتِعْمَالِه إلى قسمين ، هما :
أ- بَارِزٌ ، كالضمائر السَّابقة .
ب- مُسْتَتِرٌ ، نحو : ذَهَبَتْ ، تقديره ( هي ) ونحو : أخرجُ ، تقديره ( أنا ) .
* الضَّمائرُ كلُّها مَبْنِيَّةٌ .', 36, 36, 1
